<?php
namespace App\Commands;
use App\Services\Fiscal\FiscalStampAdminService;use CodeIgniter\CLI\{BaseCommand,CLI};
final class IkontrolStampsStatus extends BaseCommand{protected $group='iKontrol';protected $name='ikontrol:stamps-status';public function run(array$params){$service=new FiscalStampAdminService();$accounts=$service->getAccounts();$credited=0;$consumed=0;$history=[];$creditTypes=['allocation','adjustment_credit'];$consumeTypes=['document_consumption','reconciliation_consumption','cancellation_request','cancellation_status_query','cancellation_consumption','adjustment_debit'];foreach($accounts as$a){foreach($service->getHistory((int)$a['issuer_profile_id'])as$m){$q=(int)$m['quantity'];if(in_array($m['movement_type'],$creditTypes,true))$credited+=max(0,$q);if(in_array($m['movement_type'],$consumeTypes,true))$consumed+=abs($q);$history[]=$m;}}usort($history,fn($a,$b)=>(int)$b['id']<=>(int)$a['id']);CLI::write("IKONTROL_JSON_BEGIN\n".json_encode(['status'=>'SUCCESS','balance'=>array_sum(array_map(fn($a)=>(int)$a['usable_balance'],$accounts)),'credited'=>$credited,'consumed'=>$consumed,'accounts'=>$accounts,'movements'=>array_slice($history,0,20)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\nIKONTROL_JSON_END");}}
